INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.07, 2.57, '9781515421061', '1515421066', 36, 49.7, 2.05, '2018-04-03', '', 'Angel''s Egg', 1.86, 4.49, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.04, 1.15, '9781515421191', '1515421198', 44, 11.98, 2.53, '2018-04-03', 'Granthan''s mission was the most vital of the war. It would mean instant victory-but for whom? Earth didn''t trust his information. They were sure that he had been brain washed by the enemy. He had to convince them that he could be trusted before they killed him. But could he?', 'End as a Hero', 3.29, 5.38, 6, NOW(), NOW());
