INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.87, 6.91, '9781515426899', '1515426890', 180, 81.4, 3.71, '2018-04-03', '', 'The War of the Worlds', 6.96, 2.8, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.41, 2.42, '9781515426912', '1515426912', 120, 93.4, 4.47, '2018-04-03', '''On this machine, I intend to explore time ...''The time traveller has invented a time machine. Its capabilities are beyond even his fertile imagination. Hundreds of thousand of years in the future, the beautiful Eloi people live in a Garden of Eden. But why are the Eloi so fearful of the dark? What horrors lurk beneath the surface of their world? What will the time traveller learn about the future? Will he survive the evil he encounters? Even if he can find his stolen machine, will it return him safely home? What does his future hold? What is the future of the human race?', 'The Time Machine', 6.93, 7.69, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.78, 3.8, '9781515428602', '1515428605', 334, 8.69, 3.2, '2018-04-03', 'Jacob Burckhardt was born in 1818 in Basel, Switzerland. He studied history at the University of Berlin and taught art history and the Italian Renaissance in Berlin and Basel. His essay, as he called "The Civilization of the Renaissance in Italy, " was first published in 1860. Rich in its detailed account of the arts, fashions, manners, and thought of one of the most innovative eras in human history, this brilliant panorama of Renaissance life is also a thorough examination of the nature of civilization and of our place within it. Burckhardt''s encyclopedic knowledge, his mastery of style, and his genius for synthesis make this one of the few classics of history and the prototype for cultural history. Burckhardt''s "The Age of Constantine the Great" and "Cicerone" were published in his lifetime, and "The History of Greek Civilization" and "Reflections on World History" after his death in 1897.', 'Civilization of the Renaissance in Italy', 4.3, 9.04, 90, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.24, 7.3, '9781515431466', '1515431460', 206, 38.54, 4.89, '2018-04-03', '', 'A Voyage to Arcturus', 5.64, 9.25, 10, NOW(), NOW());
