INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.08, 3.87, '9788423333943', '8423333949', 202, 62.91, 1.74, '1995-09-25', '', 'Viaje a la Alcarria', 2.19, 7.09, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.79, 5.67, '9788423337217', '8423337219', 764, 90.92, 4.97, '1970-06-16', 'Olvidado rey Gudú es la obra maestra de Ana María Matute y una de las grandes novelas de este siglo. Repleta de fábulas y fantasías, narra el nacimiento y la expansión del Reino de Olar, con una trama llena de personajes, aventuras y de un paisaje simbólico: el misterioso Norte, la inhóspita estepa del Este y el Sur, rico y exuberante, que limitan la expansión del Reino de Olar, en cuyo destino participan la astucia de una niña sureña, la magia de un viejo hechicero y las reglas del juego de una criatura del subsuelo.Olvidado rey Gudú es una gran metáfora del alma humana y su historia, tejida de realidad y leyenda, de pasado y presente, alentada por los deseos y las inquietudes que desvelan al ser humano desde hace siglos.', 'Olvidado rey Gudú', 1.41, 6.51, 188, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.97, 2.33, '9788423343478', '8423343472', 176, 73.62, 3.12, '2000-05-23', 'Aranmanoth es una novela de iniciación a la vida y al amor, protagonizada por un muchacho medio humano medio mágico, hijo del Señor del Lines y de un hada de las aguas. En una Edad Media ensombrecida por guerras infinitas, Aranmanoth parte en búsqueda de su destino, alejándose de los demás mortales y obedeciendo a misteriosas señales de las hojas de los árboles y de los pájaros que atraviesan el cielo. Aranmanoth y Windumanoth, su niña amada, esposa de su padre, viajan en pos de un sueño de plenitud, hacia la tierra prometida de su infancia que, poco a poco, revela hallarse en su interior. En ese viaje por las tierras simbólicas de una Edad Media mítica y sensual, aprenderán que la belleza y el amor entrañan dolor, y que la realidad asedia siempre a los deseos y los sueños.', 'Aranmanoth', 5.86, 4.27, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.63, 5.14, '9788423667284', '8423667286', 291, 55.85, 1.48, '1994-07-16', 'Emilio learns about the events of World War II, in which his grandfather participated before his death. This knowledge leads Emilio to join a group of other survivors and heirs of the Spanish soldiers trying to put the past behind them.', 'La Puerta de Agartha', 3.54, 8.44, 8, NOW(), NOW());
