INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.96, 3.5, '9788426128157', '8426128157', 416, 97.5, 4.42, '1981-12-27', '', 'Aku-aku', 5.49, 7.25, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.78, 1.96, '9788426132406', '8426132405', 331, 52.3, 5.0, '1971-05-17', 'Hasta donde me lleve el viento es la loca rebeldía que toma Eduardo Rejduch de la Mancha para escapar de un futuro cierto y premeditado. Sin más fortuna que un velerito de ocho metros al que llamará Charrúa y los bolsillos vacíos, saldrá solitario al mar', 'Hasta donde me lleve el viento', 2.89, 4.1, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.21, 2.8, '9788426137227', '8426137229', 432, 19.55, 1.1, '2008-11-01', 'Desde Homero, el mar no ha dejado de ser fuente de inspiración. Escritores, poetas, navegantes solitarios, viajeros ocasionales, marinos de altura..., todos han mojado su pluma en tinta de mar. Porque los océanos propician viajes de los que uno nunca regre', 'Tinta de mar', 7.05, 3.3, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.06, 1.27, '9788426145963', '8426145965', 427, 53.59, 3.34, '1976-08-02', 'En 1968 el periódico The Sunday Times de Londres, propuso organizar una regata en solitario y sin escalas alrededor del mundo a un grupo de navegantes entre los que se encontraba Bernard Moitessier. Nunca se había hecho nada parecido. Aquí se inició la insólita historia que se narra en este libro: 37.000 millas marinas para llegar? al corazón de un hombre. Esta nueva edición incluye un inestimable prólogo de Julio Villar, quien compartió escala (y muchas cosas más) con Moitessier en este largo viaje.  El largo viaje es el relato de diez meses navegando en solitario. El periplo significó una vuelta y media al mundo a través del mar, que, «según el viento, según el cielo, según que el ocaso fuera rojo o gris, ruge, murmura o gime bajo el casco». En este libro descubrimos la audacia, calculada y prudente, de un marino fuera de serie que decidió llegar hasta el límite de la resistencia humana y de la de su barco, sobre un mar a veces en calma, y a veces rugiente como una fiera. Se trata de la travesía más larga en solitario: 37.455 millas sin tocar tierra.  Además de ser el relato de una pericia que pocos hombres han asumido en la historia, este libro contiene múltiples consejos, trucos y apreciaciones para aquellos apasionados de la navegación a vela más tradicional, con un apéndice de más de 100 páginas con pautas para la preparación de una navegación sin escalas de este tipo. Esta reedición revisada, contiene además materiales inéditos como múltiples fotos que realizó el autor durante su travesía y diseños realizados por el mismo. Un testimonio de la navegación de altura sin igual.', 'El largo viaje', 7.0, 8.93, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.98, 4.71, '9788426157553', '8426157556', 262, 5.98, 2.79, '1985-12-15', '', 'Siete años en el Tíbet', 1.81, 6.37, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.77, 2.42, '9788426321282', '8426321283', 78, 82.17, 2.2, '1989-08-17', '', 'En globo sobre el Golfo', 6.27, 7.61, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.23, 4.0, '9788426413239', '8426413234', 172, 66.0, 1.81, '1989-08-29', 'Siete cuentos de estirpe fantástica, deudores y renovadores de la tradición fundada por Poe, Maupassant, Borges o Cortázar. Dueño de un estilo nítido, transparente y muy eficaz, Argüello nos cuenta historias inquietantes y turbadoras, como la del hombre que cree que escribe un relato cuando en verdad es tan solo un personaje de otro relato que vive atrapado en la telaraña de la ficción. O el penúltimo relato, una pieza maestra, la historia de un escritor que viaja al futuro para comprobar si ha ingresado en la historia de la literatura.', 'Siete cuentos imposibles', 4.2, 8.75, 191, NOW(), NOW());
