INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.35, 6.35, '9788427010123', '8427010125', 186, 4.01, 1.83, '1994-09-21', 'Again the adventurers, Fafhrd and the Gray Mouser continue their travels. Lankhmar holds bitter memories behind its walls, but Fafhrd and the Gray Mouser cannot resist the lure of the decadent civilization and, after many wanderings - in which they were not able to find work as mercenaries -always and inevitably end up returning to frequent taverns and twisted alleys.', 'Espadas contra la muerte', 2.16, 1.42, 193, NOW(), NOW());
