INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.19, 9.05, '9788427016484', '8427016484', 430, 27.85, 4.63, '1979-08-19', 'Cheradenine Zakalwe, born outside of the Culture, was recruited into it by Special Circumstances and works as an operative secretly intervening in less advanced civilizations.', 'El uso de las armas', 8.04, 1.09, 9, NOW(), NOW());
