INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.39, 2.19, '9788440617514', '8440617518', 426, 97.82, 2.79, '1978-09-10', '', 'El Mundo al final del tiempo', 4.35, 9.56, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.78, 8.97, '9788440619518', '8440619510', 243, 50.41, 1.35, '1989-01-02', '"Un respetable y célebre doctor de la Inglaterra victoriana se siente inevitablemente arrastrado al vicio, la violencia, y el crimen."--Cover.', 'El Extraño caso del Dr. Jekyll y Mr. Hyde', 9.1, 8.96, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.19, 8.68, '9788440622884', '8440622880', 253, 81.58, 1.45, '1989-06-24', '', 'El Dragón en el mar', 1.0, 8.23, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.19, 2.42, '9788440625465', '8440625464', 317, 30.45, 4.62, '1994-05-30', 'Only a few nuclear bombs fell on North America, but that was enough to create nearly total destruction. But in the midst of the chaos a few civilized places remained. The strongest of these was the state of Deseret, in the Great Basin, where the climate had changed and the prehistoric lake refilled. There, on the fringe, valiant pioneers are making the desert blossom like a rose.', 'La Gente del margen', 1.17, 1.42, 4, NOW(), NOW());
