INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.7, 2.48, '9788477224112', '8477224110', 608, 77.6, 2.08, '1998-01-22', 'The legends of King Arthur come alive with a Christian world-view in these masterfully told adventures. These new editions contain new maps and other new material.', 'Merlin', 7.33, 9.96, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.21, 2.4, '9788477224136', '8477224137', 326, 16.05, 3.25, '1995-03-01', 'David Day ha escrito un completo bestiario que incluye los nombres de las criaturas y monstruos imaginados por Tolkien, así como una exhaustiva relación de razas, ciudades, reinos, deidades, flora, batallas y los infinitos sucesos que tuvieron lugar en la Tierra Media.', 'Bestiario de Tolkien', 1.52, 8.92, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.15, 2.16, '9788477226451', '8477226458', 508, 73.81, 4.21, '1996-06-01', '"Historia de Ariano, el reino del cielo, un mundo de islas que flotan en el aire donde humanos, elfos y enanos luchan por el control del bien más preciado: el agua."--Jacket.', 'Ala de dragón', 8.23, 6.04, 8, NOW(), NOW());
