INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.92, 5.67, '9788477868552', '8477868557', 316, 73.89, 2.8, '1976-10-21', 'Se presenta, en edición facsimilar y precedida por una biografía del autor, la obra de D. Antonio de Ulloa, Conversaciones de Ulloa con sus tres hijos en servicio de la Marina.', 'Conversaciones de Ulloa con sus tres hijos en servicio de la marina', 3.1, 9.18, 220, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.89, 9.25, '9788477903550', '8477903557', 1489, 48.11, 2.75, '2003-05-31', '', 'Caminería hispánica: Caminería física', 3.46, 2.45, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.3, 6.13, '9788478083268', '847808326X', 123, 98.35, 2.86, '1993-04-18', 'Todos buscamos el verdadero amor, pero que espera el Universo de nosotros? Como podemos entregarnos y rendirnos totalmente para, de este modo, permitir que el Universo se nos revele indicandonos el camino a seguir? Lo que parecen obstaculos, muchas veces no son sino tropiezos magicos. Desbordante de humor e inspiracion, este relato nos da la respuesta. Con sus inocentes ilustraciones y la poetica sencillez de sus textos, sin duda renovara tu fe en el inmenso poder del amor.', 'El Hombre que no podía verse a sí mismo', 7.71, 2.15, 221, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.75, 4.39, '9788478130658', '8478130659', 218, 37.82, 3.06, '1971-09-29', '', 'Los Clanes de la Luna Alfana', 9.25, 3.59, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.66, 4.15, '9788478132621', '8478132627', 327, 88.22, 1.74, '2003-01-01', 'Textos de Antonio Pigafetta, Juan Sebastián Elcano, Francisco Albo, Ginés de Mafra, Maximiliano Transilvano y otros describiendo el primer viaje de circunnavegación del globo terrestre iniciado por Fernando de Magallanes en 1519 y culminado por Elcano en 1522', 'La primera vuelta al mundo', 1.96, 1.26, 222, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.16, 6.29, '9788478266951', '847826695X', 136, 74.58, 1.77, '1999-02-28', '', 'De Rusiñol a Monzó', 3.79, 2.17, 223, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.19, 2.12, '9788478268177', '8478268170', 72, 28.23, 3.47, '1990-06-11', '', 'Viatgers catalans al Carib', 4.91, 9.72, 223, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.5, 1.07, '9788478442621', '8478442626', 364, 95.86, 2.33, '1995-02-01', 'En otono de 1973 el escritor Peter Matthiessen y el zoologo George Schaller emprendieron una expedicion a la Montana de Cristal, en la meseta del Tibet, para estudiar los habitos de un animal no muy conocido: el bharal o cordero azul himalayo. Pero su autentica esperanza era poder ver al mas hermoso y raro de los grandes felinos: el leopardo de las nieves.Para Matthiessen, adentrarse en la tierra de Dolpo, ultimo enclave de la cultura tibetana en estado puro, significara mucho mas que una expedicion naturalista o una aventura: despojarse de las ventajas y las ataduras de la civilizacion, convivir con hombres y paisajes en su mas elemental belleza, penetrar en si mismo por las vias que le proporciona el budismo o el zen: ahi estan, abiertas y sugerentes, las huellas del leopardo de las nieves. B+Un hombre sale de viaje y es otro quien regresa.B; Ese es el sentido del viaje de Matthiessen, como lo es de todo autentico viaje.', 'El leopardo de las nieves', 5.32, 9.11, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.39, 5.74, '9788478463206', '8478463208', 398, 92.72, 2.92, '1994-01-01', '', 'Por los caminos de la trashumancia', 6.99, 3.92, 224, NOW(), NOW());
