INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.5, 2.78, '9788481090840', '8481090840', 155, 57.18, 4.61, '1999-05-19', '', 'Yo he vivido en la Antártida', 6.33, 4.36, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.08, 7.53, '9788482562544', '8482562541', 519, 88.97, 4.29, '1991-03-08', '', 'El Silmaríl·lion', 5.95, 7.42, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.92, 4.56, '9788482641652', '8482641654', 152, 90.21, 2.35, '1984-04-04', '', 'Ofici d''amant a Florència', 4.37, 6.75, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.07, 7.18, '9788482642772', '8482642774', 278, 52.55, 1.28, '1976-04-18', 'Bilbo, el h:amp;ograve;bbit, :amp;eacute;s amic de l:amp;#39;exist:amp;egrave;ncia ben reglamentada i de costums inamovibles. Per:amp;ograve; :amp;eacute;s, alhora, hereu de l:amp;#39;esperit aventurer del seu avantpassat viatger. I :amp;eacute;s aquest esperit que encoratjar:amp;agrave; el mag Gandalf per viure, juntament amb Bilbo, les grans aventures d:amp;#39;aquesta novel:amp;middot;la. Temes: Mitologia, :amp;eacute;ssers fant:amp;agrave;stics, aventures, amistat.', 'El Hòbbit', 1.06, 7.35, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.82, 5.16, '9788482646954', '8482646958', 448, 53.53, 4.22, '1970-11-19', 'Possedor d’un dels talents mes visionaris del segle XX, Ray Bradbury ens va deixar alguns contes que són obres mestres del genere. En aquest volum trobarem trenta-dos relats cabdals que revelen el Bradbury mes imaginatiu, pero sobretot hi retrobarem un escriptor tendre, capaç d’explicar, amb la historia d’un individu o d’un fet mínim, tota una visió dramàtica sobre l’home i allo que l’espera. Un autor que ens ha dotat de figures i símbols que ens ajuden a entendre l’univers que habitem, com ara el celebre "efecte papallona", expressat amb gran encert en el conte "El so d’un tro". Gràcies a Bradbury retrobem allo meravellós, el mes terrible i el mes sublim, l’inesperat i el malson que es transforma en una visió obsessionant i lúcida sobre la nostra condició.', 'Les pomes daurades del sol', 3.67, 9.96, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.67, 2.13, '9788482983431', '8482983431', 149, 77.43, 4.35, '1989-01-31', '"Afortunado es -escribe Robert Hughes- quien descubre una ciudad, que no es la suya de origen, que se convierte en su hogar... Hace unos cuarenta años, tuve ese maravillosos golpe de suerte: Barcelona."Hoy, doce años después de su clásica y famosa crónica Barcelona, la buena suerte de Hughes es evidente aquí en este retrato personal, cariñoso y fascinante de la capital catalana.Esta es la historia de Hughes -desde su primera visita en 1966 hasta su reciente boda en el histórico Saló de Cent-, entrelazada con la historia de Barcelona, sus orígenes como puesto avanzado romano, dos milenios de cultura ferozmente independiente y su moderna encarnación en una de las ciudades más dinámicas de Europa. Habla el autor del excéntrico genio de Antoni Gaudí, cuyos asombrosos y fantásticos diseños son la herencia arquitectónica de cien años, del simple pero exquisito placer de una butifarra catalana o la cautivadora e hipnóticamirada del Pantocrátor en un nural de 900 años de antigüedad. Es éste un estupendo tributo a una ciudad singular, de un buen conocedor y famoso crítico de arte.', 'Barcelona, la gran hechicera', 6.46, 6.92, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.62, 2.95, '9788483071496', '8483071495', 294, 48.69, 3.64, '1996-06-17', '', 'Los Últimos bárbaros', 9.65, 9.84, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.5, 3.19, '9788483072349', '8483072343', 185, 28.47, 2.36, '1985-02-17', 'Enric González nos cuenta en Historias de Londres los curiosos avatares que lo llevaron hasta la capital de Inglaterra y la inextricable relación amorosa que trabó con ella de inmediato. Tomando como pretexto los pequeños acontecimientos de su día a día (los chismorreos y fisgonesos de venicos; los plácidos paseos; la tensión de los desplazamientos, el trabajo y las enfermedades; las horas de recreación gracias a los más variados espectáculos), esto es, un elenco de situaciones y perplejidades, el autor nos va desgranando e iluminando algunos rincones afamados y recónditos de Londres: ¿Por qué la vida es tan restallante en Notting Hill? ¿Qué historia tétrica guarda un pub como el Ten Bells? ¿Cómo es un ritual go-do-yin en Brixton?¿Por qué es preferible ser forofo del Chelsaea a aserlo del Arsenal? Así, estas Historias de Londres (a veces cósmicas, a veces graves, siempre un punto melancólicas) nos muestran la miseria y la grandeza de la sanidad, la economía, la arqueitectura, la cultura, el fútbol y otros aspectos característicos de Londres, de manera que el lector no dejará de senitrse fascinado por una ciudad que cambia de piel en la pluma de alguien que, mientaras estuvo allí, se sintió como pez en el agua y que siempre piensa en volver y volver...', 'Historias de Londres', 3.53, 6.32, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.39, 9.03, '9788483072592', '8483072599', 246, 43.52, 1.61, '1977-05-14', '', 'En la Patagonia', 6.74, 7.13, 229, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.64, 5.11, '9788483072936', '8483072939', 335, 84.28, 1.93, '1984-01-02', '', 'La Sombra del Kilimanjaro', 3.36, 5.68, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.93, 6.52, '9788483072981', '848307298X', 103, 41.64, 2.43, '1976-11-10', '', 'El redescubrimiento de América', 3.99, 9.18, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.55, 9.09, '9788483074640', '8483074648', 351, 91.32, 4.44, '2002-01-01', 'Venecia es, probablemente, una de las ciudades que más pasiones ha despertado entre todos aquellos que, a lo largo de los siglos, han sido sus huéspedes. Cuando Jan Morris llegó a Venecia a finales de los cincuenta no pudo sustraerse al encanto que emanab', 'Venecia', 4.66, 3.19, 229, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.43, 7.05, '9788483074923', '8483074923', 0, 60.53, 3.45, '1995-01-02', 'En el corazón de Turquía, piedras formadas por la erupción de volcanes y esculpidas por la nieve y el viento, ciudades subterráneas construidas por el hombre para ocultarse y defenderse y maravillosos ejemplos de arte religiosos atraen y seducen a los visitantes. Fascinados ante aquellas torres cilíndricas de remate curvilíneo escamoso, Juan Goytisolo imaginó a un Gaudí eremita y centenario frente al paisaje de Capadocia, que hubiera quedado deslumbrado por las formas que crearon erupciones volcánicas y fenómenos climáticos en esta región del centro de Turquia. En Aproximaciones a Gaudí en Capadocia se reúnen una serie de textos que, junto con el que da título al libro, configuran un variado retable de un mundo fascinante y abigarrado. Las modulaciones y estructuras del paisaje turco, los volúmenes de las construcciones naturales y humanas, las formas de convivencia personal y familiar son el vehículo para expresar nuevas formas de conocimiento y de amor.', 'Aproximaciones a Gaudí en Capadocia', 2.58, 5.45, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.07, 7.45, '9788483076255', '848307625X', 224, 34.14, 4.17, '2000-02-12', 'André Gide (París, 1869-1951) fue novelista, poeta, dramaturgo, crítico literario y viajero. Su obra, que se inicia en 1891 con la publicación de Los cuadernos de André Walter, es amplísima, miles de páginas que abarcan casi todos los géneros. Siempre a la vanguardia de algunas de las grandes causas del siglo XX, fustigó el colonialismo, reivindicó la homosexualidad, se convirtió al comunismo para terminar abjurando de él: a su muerte, en 1951, la izquierda le aborrecía tanto como la derecha. En 1947 le fue concedido el premio Nobel. Sus obras más destacadas son Los alimentos terrenales (1897), El inmoralista (1902), Los sótanos del Vaticano (1914), Corydon (1924), Los monederos falsos (1925), y el Diario, para muchos su obra cumbre. En julio de 1925, André Gide emprendió un viaje a las posesiones francesas de África ecuatorial como enviado especial del Ministerio para las Colonias. De aquella estancia, que duró aproximadamente un año, surgió este Viaje al Congo, una dura crítica de la política colonial del Elíseo que tenía muy poco que ver con otras obras contemporáneas escritas al dictado de determinados intereses políticos o comerciales. El libro, que provocó una verdadera convulsión política en Francia, no es tan sólo un testimonio vivo de una de las actuaciones más infamantes del hombre blanco en el continente negro, sino uno de los grandes exponentes de la literatura de viajes de todos los tiempos. «Hay muchos libros de viajes que me han aportado mucho. Pero si he de señalar algunos me inclinaría por El coloso de Maroussi de Henry Miller y el Viaje al Congo de André Gide; Vía de escape, de Graham Greene y cualquiera de Manu Leguineche, un artista en este tipo de género, por ejemplo: El camino más corto».JAVIER REVERTE', 'Viaje al Congo', 3.1, 6.47, 229, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.68, 9.75, '9788483652503', '8483652501', 406, 28.04, 1.78, '1996-05-14', 'El juicio final está en camino, y Sookie tiene una habilidad especial para situarse en medio del camino de los problemas; en particular cuando es testigo del ataque con bombas incendiarias al Merlotte''s, el bar donde trabaja. Dado que Sam Merlotte es conocido por su doble naturaleza, las sospechas inmediatamente recaen sobre los cambiantes de la zona. Sookie tiene otra opinión, pero antes de que pueda investigar surge algo, aún más peligroso. El amante de Sookie, Eric Northman, y su “niña” Pamela están tramando algo en secreto. Sea lo que sea, parecen decididos a mantener a Sookie al margen. Pero Sookie está igual de decidida a descubrir qué está ocurriendo. No puede permanecer de brazos cruzados cuando tanto su trabajo como su vida amorosa están amenazados. Sin embargo, cuanto más se progresa en sus planes, más consciente es de que la situación es más mortal de lo que nunca hubiera podido imaginar.', 'El día del juicio mortal', 3.12, 8.28, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.01, 4.62, '9788483670118', '8483670119', 118, 37.31, 3.97, '1995-04-24', 'Hace algunos años, en el diario barcelonés La Vanguardia, el novelista y crítico literario Sebastián Juan Arbó decía que la novela de Víctor Alperi, El rostro del escándalo, figuraba entre las cinco novelas españolas que se podían com', 'España, un corazón desnudo', 6.24, 6.99, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.28, 8.58, '9788484214205', '8484214206', 212, 64.04, 4.28, '2001-01-01', 'Podría un miserable actor sustituir al político más famoso del imperio? Lorenzo Smith sintió un hormigueo en su cuerpo cuando le propusieron el trabajo, ya que Bonforte era el político más reputado en la Galaxia. Sería un gran desafío dar vida a este personaje, por supuesto. Pero cuando estudió el papel vio muy claro que se encontraba ante una peligrosa misión de cuyo resultado dependía el destino del Sistema Solar... La obra de Robert A. Heinlein se caracteriza por un dominio absoluto de la trama y los diálogos, que confieren gran agilidad a sus relatos, esencialmente de acción y marcado realismo. Alcanzó muy pronto la celebridad en el género y se convirtió, merced a lo ingente, en calidad y cantidad de su producción en una de las figuras norteamericanas más influyentes y controvertidas.', 'Estrella Doble', 6.99, 4.11, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.98, 2.5, '9788484272816', '8484272818', 172, 72.37, 2.58, '1995-08-31', 'Existe poca literatura científica y divulgativa acerca de los viajes en el mundo antiguo. Los escritores de la antigüedad, al menos en las obras conservadas, raramente se ocuparon de los detalles acerca de los viajes y desplazamientos. Desde el surgir de la civilización, en Próximo Oriente Asiático y Egipto, se produjeron viajes que tuvieron motivaciones diversas: militares, comerciales, administrativas, religiosas. En Grecia los viajes por mar se convirtieron en una seña de identidad, como define el que en el propio origen de la literatura, la Odisea sea, en una buena parte, no sólo un relato de aventuras sino un viaje por mar. Y con la unificación romana del mundo mediterráneo, la actividad viejera adoptó dimensiones considerables, tanto por mar (en el lago del Mare Nostrum) como por tierra, quedando el testimonio del espectacular trazado de las calzadas. Todas estas civilizaciones, y las principales motivaciones de los viajes, tratan de ser resumidas en el presente trabajo, realizado fundamentalmente a partir de los testimonios literarios, con el que se intenta llenar un vacío existente en la historiografía de la antigüedad en nuestro país.', 'Viajes y viajeros en el Mundo Antiguo', 2.34, 2.07, 230, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.25, 7.13, '9788484280460', '8484280462', 352, 14.25, 3.9, '2000-10-25', '«La ruta de Alejandro» es la crónica de un viaje que la autora emprendió en 1954 y que podríamos calificar de histórico-literario. Freya Stark se propone seguir la ruta de Alejandro Magno partiendo de Aleppo y recorriendo, según los textos clásicos que se pueden obtener, prácticamente toda la actual Turquía para así recrear y desentrañar la ruta y vicisitudes que vivió Alejandro Magno. Un libro de viajes, que añade al interés histórico y geográfico una alta dosis de humor.Freya Stark nació en París en 1893. Hija de artistas, tuvo una infancia trashumante. Publicó su primer libro, «The Valley of the Assassins» en 1934, una mezcla de guía de viaje y comentarios personales de los lugares que recorre. Durante la Segunda Guerra Mundial trabajó para el Ministerio de Información británico. Al acabar la guerra siguió con sus viajes y publicó en total dos docenas de libros, entre los que destacan «The Southern Gates of Arabia» (1936), «Letters from Syria» (1942) y «La ruta de Alejandro» (1958). Freya Stark murió en 1993.', 'La Ruta de Alejandro', 6.59, 7.64, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.06, 5.71, '9788484370147', '8484370143', 301, 30.02, 1.17, '1987-09-15', '', '2001, una odissea a l''espai', 7.33, 6.84, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.46, 3.53, '9788484372400', '8484372405', 228, 16.24, 2.88, '1984-06-23', 'Potser és millor la violència que no pas la inèrcia. Aquest dubte percudeix, com un cop de puny al ventre, la consciència del lector de La taronja mecànica. Alex i la seva colla viuen en una època inconcreta, un futur similar als malsons d''Orwe .', 'La Taronja mecànica', 3.66, 1.3, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.26, 9.67, '9788484372837', '8484372839', 263, 94.92, 4.18, '2001-01-01', 'Una mordaz sátira acerca de la industria armamentística.En 2002 los Protocolos de Arado sentaron las bases para la carrera armamentística de los grandes bloques de la influencia de la Tierra. Lars Powerdry es el diseñador de armamento más brillante del Bloque-Occidente, capaz de inventar los artefactos más elaborados. Pero cuando unos satélites alienígenas hacen su aparición en la órbita terrestre dejando claro que sus intenciones no son amistosas, el mundo necesitará más potencia militar que nunca.Por eso, en ambos bandos dejan a un lado sus diferencias y Lars tiene una reunión con Lilo Topchev, su homóloga del Pío-Oriente, con la esperanza de crear un arma capaz de salvar el mundo. No es una tarea sencilla, mucho menos cuando Lars se enamora de Lilo a pesar de que sabe que ella intenta matarlo... «Un híbrido entre Dickens y Dostoievski, poseído por la deliciosa comicidad y la profundidad trágica de ambos... Dick entretiene, cautiva y sorprende a sus lectores.»—Brian W. Aldiss. La pistola de rayos es una mordaz sátira acerca de la industria armamentística que sigue tan vigente hoy día como en plena guerra fría.', 'Blade Runner', 2.6, 9.37, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.08, 8.52, '9788484375173', '848437517X', 136, 22.14, 1.42, '1977-05-20', 'Descubre el calendario Tolkien 2015, con ilustraciones originales de la trilogía de El señor de los anillosComo cada año, los fans del mundo creado por J. R. R. Tolkien tienen una cita con el Calendario Tolkien. Este año estará dedicado a la trilogía deEl Señor de los Anillos, con ilustraciones de Mary Fairburn, la ilustradora que trabajó en la obra de Tolkien hace cuarenta y cinco años y que ha decidido crear nuevos originales que encantarán a los fans de la saga.', 'Gil, el pagès de Ham', 1.08, 1.46, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.41, 2.81, '9788484378112', '848437811X', 213, 80.32, 1.48, '2003-02-28', 'Les tombes d''Atuan és el segon volum de la tetralogia de Terramar, iniciada amb Un mag de Terramar, publicat també en aquesta col·lecció. El mag Ged segueix aquí la seva educació vital, el seu recorregut iniciàtic.', 'Les Tombes d''Atuan', 2.77, 2.51, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.06, 8.6, '9788484410355', '8484410358', 448, 26.43, 1.56, '1986-10-30', 'For use in schools and libraries only. The warrior mouse Matthias and his friends must leave the Abbey undefended as they pursue Slagar, who has kidnapped the children of Redwall, including Mattimeo, Matthias''s son. Reissue.', 'Mattimeo', 8.57, 7.73, 231, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.25, 3.51, '9788484501312', '8484501310', 728, 73.39, 4.59, '1999-02-13', '', 'Jerusalén', 8.51, 2.35, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.19, 8.54, '9788484502548', '8484502546', 485, 29.9, 3.0, '1978-12-09', 'Transcurre una apacible tarde de verano en Wentworth, Ohio. como es habitual, en la soleada calle Poplar todo es normal: el chico de los periódicos los reparte en bicicleta, los niños juegan en las aceras, las barbacoas se preparan en los jardines y patios. Lo único extraño es la furgoneta roja que hay aparcada en una esquena. El misterioso vehículo no tardará en ponerse en marcha... y con él se desencadenará una atroz matanza. Cuando la noche caiga, los supervivientes del vecindario se encontrarán en un mundo pavoroso donde cualquier cosa es posible.', 'Posesión', 6.5, 3.55, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.86, 9.71, '9788484505266', '848450526X', 320, 57.28, 1.61, '2003-02-22', 'En este libro la autora narra su viaje por Siria en 1993. La historia, la geografía, la sociedad y la vida cotidiana de este país subyugante resultan magníficamnte retratadas, ofreciéndonos un fresco exhaustivo y apasionante de una cultura milenaria.', 'Viaje a la luz del Cham', 5.34, 4.38, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.41, 2.91, '9788484506362', '8484506363', 317, 31.18, 2.22, '1990-03-23', 'Mortimer es un joven soñador y despistado a quien le toca en suerte una inesperada tarea: convertirse en aprendiz de la Muerte y aplicarse en liberar almas de su envoltura carnal. La verdad, Mort no está demasiado capacitado para ello, y en una de sus primeras misiones, liberar el alma de una atractiva princesa que está a punto de ser asesinada, decide en su lugar ''liberar'' el alma del asesino, interfiriendo así en los designios del destino y provocando el consiguiente desaguisado', 'Mort', 9.95, 4.73, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.8, 4.93, '9788401376757', '8401376750', 205, 65.21, 4.49, '2000-09-27', 'Sin descripción disponible', 'Los Fantasmas del Everest', 1.53, 7.59, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.17, 4.97, '9788484531357', '848453135X', 476, 17.38, 1.7, '1972-04-03', 'Este es un relato de aventuras propulsado por una voraz curiosidad, una apasionante investigación arqueológica y un conmovedor viaje interior. Bruce Feiler escribe la crónica de su odisea de miles de kilómetros -a pie, en un todoterreno, en barca y en camello- por las tierras ancestrales y peligrosas del Oriente Medio actual para descubrir la persistencia del patrimonio cultural y religioso que nos configura. Guiado por los cinco libros iniciales de la Biblia y por el arqueólogo Avner Goren, Feiler recorre tres continentes, cinco países y cuatro regiones en conflicto bélico -es la primera persona en completar semejante trayecto- a fin de responderse si el relato bíblico es mera abstracción o una realidad vibrante. Desde el monte Ararat en Turquía, donde se asentó el Arca de Noé, hasta Jordania, donde Moisés eludió la Tierra Prometida, este periplo explora, escrupulosamente, los descubrimientos arqueológicos recientes, además de la intrincada geografía humana que les da relieve, y desmantela nuestros vagos prejuicios con una mirada refrescante y perspicaz.', 'Recorriendo la Bíblia', 9.29, 4.41, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.19, 3.96, '9788484600060', '8484600068', 220, 50.45, 2.02, '2002-01-31', 'Se trata del relato de la ascensión de este alpinista al pico del K2, y la tragedia que se produció más tarde.', 'Cita con la cumbre', 8.56, 8.15, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.58, 8.08, '9788484605584', '8484605582', 240, 33.96, 4.19, '2005-12-17', 'Tras el éxito alcanzado con el primer volumen, podemos disfrutar de nuevas y magníficas "perlas" que se reúnen en este amplio y disparatado repertorio para provocar la carcajada de sus lectores. Ni la LOGSE ni eso de la ESO han acabado con los disparates estudiantiles. Si alguna vez has pasado el mal trago de un examen, seguro que te divertirás con esta completa colección de respuestas absurdas.', 'Gran enciclopedia del disparate 2', 9.05, 8.65, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.96, 5.03, '9788484605751', '8484605752', 144, 98.34, 1.85, '1991-05-17', 'El rey del pesimismo ataca de nuevo y esta vez para... ¡hablar del amor! No escapan a su lengua mordaz, a su despiadada mirada, ni los jóvenes enamorados, ni los recién casados, ni los que se han metido en el lío de ser padres, ni las parejas que, a pesar de todo, llegan a cumplir sus bodas de oro. Desde el momento del flechazo o la cita a ciegas, hombres y mujeres viven como en una nube, encantados con su pareja, sin saber que las cosas irán necesariamente de mal en peor. • Es imposible amar y ser sabio a la vez. • En una relación, la imperfección oculta nunca permanece oculta. • El sexo es una de las nueve razones que existen para creer en la reencarnación. Las otras ocho carecen en absoluto de importancia. • Cuando la esposa de un hombre aprende a comprenderle, por lo general deja de escucharle. • El que ronca es el que siempre se duerme primero. Si usted opina, como Murphy, que el amor es el triunfo de la imaginación sobre la inteligencia, no dude en leer este libro. No hará sino confirmarle que, en efecto, es así.', 'La Ley de Murphy del amor', 8.74, 1.19, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.97, 3.65, '9788485354726', '8485354729', 109, 88.68, 1.46, '1981-01-23', '', 'España negra', 2.49, 6.95, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.29, 3.47, '9788485411511', '848541151X', 360, 43.28, 5.0, '1972-01-20', '', 'Lope de Aguirre', 6.44, 5.49, 232, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.75, 3.21, '9788485639298', '8485639294', 103, 25.02, 3.91, '1995-12-20', '', 'Cartas del descubrimiento del Gran Catayo', 9.07, 7.32, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.4, 5.84, '9788485639366', '8485639367', 259, 90.88, 2.43, '2001-12-24', 'Descripción del viaje (1403-1406) que por encargo del Rey Enrique III de Castilla realizó el autor a la mítica Samarcanda de Tamerlan, siendo éste el primer libro de viajes de la literatura castellana. La minuciosidad de las noticias y descripciones...', 'Embajada a Tamerlán', 3.59, 7.4, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.66, 6.95, '9788485707393', '8485707397', 190, 44.63, 1.1, '2003-02-14', '190 páginas, Ilustraciones de Raymond Sheppard, Gran formato 21,5x29 cm, Cartoné con sobrecubierta. Emocionante historia en la cual el coronel Corbett hace un relato de su campaña contra un leopardo que sembró el pánico durante ocho años entre los pobladores del territorio Garhwal. Por fin acabó con él tras diez semanas de asedio y persecución.', 'El leopardo devorador de hombres de Rudrapratag', 2.01, 2.81, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.62, 7.29, '9788486478735', '8486478731', 413, 62.5, 1.05, '1997-01-01', 'La vida de nuestros santos escrita de forma simpática, educativa y amena. La cultura hagiográfica es poco conocida, y a pesar de estar muy arraigada en nuestra cultura popular, pocos de nosotros conocemos la vida y anécdotas de nuestros santos. Ahora, Luis Carandell con su magnífica pluma y Alfonso Ortuño con sus geniales ilustraciones a todo color, nos presentan la vida de nuestros santos de forma simpática, educativa y amena. En cada página se describe el santo más representativo del día y se incluyen también los nombres de otros santos que se celebran en el día. Cada mes contiene una ilustración, lámina a todo color que representa el santo más emblemático del mes. Contiene, además, un índice onomástico para que todos podamos saber el día que se celebra nuestro santo.Siguiendo las hagiografías antiguas, Carandell ha reescrito esta «Leyenda Dorada» que es parte esencial de nuestra herencia literaria. Alfonso Ortuño ha utilizado en sus ilustraciones los símbolos y atributos de los santos que aparecían en las estampas tradicionales, imprimiéndoles su sello especial.', 'El santoral de Luis Carandell', 4.21, 1.05, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.94, 7.53, '9788486491444', '8486491444', 209, 44.81, 2.77, '1991-01-01', 'El primer viatge d''Espinàs per terres valencianes. La seducció narrativa de l''escriptor fa que el lector visqui l''aventura de cada pàgina. 7a edició.', 'A peu per l''Alt Maestrat', 9.77, 5.23, 233, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.68, 5.68, '9788486629533', '8486629535', 296, 74.53, 2.46, '1991-01-01', '', 'Expediciones africanas y ártica del Duque de Algeciras, 1925-1955', 1.22, 4.34, 4, NOW(), NOW());
